import{_ as s,o as n,c as e,a2 as i}from"./chunks/framework.Dsf4_p3t.js";const g=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1787565302000}'),t={name:"zh/guide/architecture.md"};function p(l,a,d,o,c,r){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>NeoFlux 采用两层架构，层间通过无锁环形队列通信。</p><h2 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to &quot;架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Application Layer (主线程)                           │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────┐  ┌──────────────────┐   │</span></span>
<span class="line"><span>│  │ Widget   │  │ Taitank  │  │ EventLoop +      │   │</span></span>
<span class="line"><span>│  │ Tree     │→ │ Layout   │  │ Coroutines       │   │</span></span>
<span class="line"><span>│  └──────────┘  └──────────┘  └────────┬─────────┘   │</span></span>
<span class="line"><span>│                                       │              │</span></span>
<span class="line"><span>│                              RenderCommand           │</span></span>
<span class="line"><span>│                                       ▼              │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  SPSC RingQueue (无锁, FIFO)                 │   │</span></span>
<span class="line"><span>│  └───────────────────────┬──────────────────────┘   │</span></span>
<span class="line"><span>└──────────────────────────┼──────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>┌──────────────────────────▼──────────────────────────┐</span></span>
<span class="line"><span>│  Render Layer (渲染线程)                             │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌─────────────────┐    ┌──────────────────────┐    │</span></span>
<span class="line"><span>│  │ RenderCommand   │    │ tgfx (移动端)         │    │</span></span>
<span class="line"><span>│  │ Consumer        │───▶│ GLFW + OpenGL (桌面) │    │</span></span>
<span class="line"><span>│  └─────────────────┘    └──────────────────────┘    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="application-层" tabindex="-1">Application 层 <a class="header-anchor" href="#application-层" aria-label="Permalink to &quot;Application 层&quot;">​</a></h2><p>运行业务逻辑，构建 Widget 树，通过 Taitank flexbox 引擎计算布局，记录渲染命令。</p><p>核心组件：</p><ul><li><strong>Application</strong>：框架入口，管理窗口、事件循环、路由栈</li><li><strong>EventLoop</strong>：信号量驱动的帧调度，协程调度器，定时器队列</li><li><strong>RouteRegistry</strong>：路由注册表，支持路由注册与导航栈</li><li><strong>Widget Tree</strong>：Widget 组成的 UI 树，Taitank 节点绑定</li></ul><h3 id="帧流水线" tabindex="-1">帧流水线 <a class="header-anchor" href="#帧流水线" aria-label="Permalink to &quot;帧流水线&quot;">​</a></h3><p>Application 层每帧按以下顺序执行：</p><ol><li><strong>轮询事件</strong> — 平台桥接输入事件分发到 Widget 树</li><li><strong>构建脏 Widget</strong> — 标记了 <code>MarkNeedsBuild()</code> 的 Widget 被重建</li><li><strong>布局</strong> — <code>Taitank::DoLayout</code> 计算 Widget 位置和大小</li><li><strong>绘制</strong> — 每个 Widget 的 <code>Paint()</code> 方法生成 <code>RenderCommand</code></li><li><strong>提交</strong> — 命令推入 SPSC 环形队列</li></ol><p>仅当 <code>frame_dirty_</code> 标志被设置时（输入事件、路由变更、<code>MarkFrameDirty()</code>）才处理帧，减少空闲 CPU 占用。</p><h2 id="render-层" tabindex="-1">Render 层 <a class="header-anchor" href="#render-层" aria-label="Permalink to &quot;Render 层&quot;">​</a></h2><p>从 SPSC 环形队列消费命令，使用 tgfx 执行绘制。</p><ul><li><strong>桌面端</strong>：通过 GLFW 创建窗口与 OpenGL 上下文，tgfx 渲染到 GL framebuffer</li><li><strong>移动端</strong>：tgfx 直接渲染到平台提供的 Surface（ANativeWindow / CAMetalLayer）</li></ul><h3 id="桌面端渲染-glfw-bridge" tabindex="-1">桌面端渲染（GLFW Bridge） <a class="header-anchor" href="#桌面端渲染-glfw-bridge" aria-label="Permalink to &quot;桌面端渲染（GLFW Bridge）&quot;">​</a></h3><p><code>GlfwBridge</code> 继承 <code>PlatformBridge</code>，封装：</p><ul><li>窗口创建与调整大小</li><li>鼠标/键盘输入回调</li><li>OpenGL 上下文管理</li><li>帧缓冲区大小查询</li></ul><h3 id="移动端渲染-tgfx" tabindex="-1">移动端渲染（tgfx） <a class="header-anchor" href="#移动端渲染-tgfx" aria-label="Permalink to &quot;移动端渲染（tgfx）&quot;">​</a></h3><p><code>MobileBridge</code> 提供平台 Surface，tgfx 统一 2D 图形 API，底层对接平台原生图形 API（Vulkan/Metal/GLES）。</p><h2 id="spsc-环形队列" tabindex="-1">SPSC 环形队列 <a class="header-anchor" href="#spsc-环形队列" aria-label="Permalink to &quot;SPSC 环形队列&quot;">​</a></h2><p>无锁单生产者单消费者有界环形缓冲区：</p><ul><li><strong>生产者</strong>：Application 层（主线程）</li><li><strong>消费者</strong>：Render 层（渲染线程）</li><li><strong>容量</strong>：<code>--render_queue_capacity</code> 配置（默认 2048），自动向上取整为 2 的幂</li><li><strong>元素</strong>：<code>RenderCommand</code> 扁平结构体（draw rect、draw rounded rect、draw text、clip、translate、save/restore、begin/end frame）</li></ul><p>队列使用缓存行对齐的原子 head/tail 计数器避免伪共享，<code>std::construct_at</code> / <code>std::destroy_at</code> 安全构造/析构元素，支持 <code>std::string</code> 等非平凡可拷贝类型。位运算回绕（<code>index &amp; (capacity - 1)</code>）替代取模。</p><h3 id="位运算索引回绕" tabindex="-1">位运算索引回绕 <a class="header-anchor" href="#位运算索引回绕" aria-label="Permalink to &quot;位运算索引回绕&quot;">​</a></h3><p>容量向上取整为 2 的幂（<code>std::bit_ceil</code>），使索引回绕使用单次位运算 AND 而非整数取模：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// SpscRingQueue 中：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mask_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // 例如 capacity=2048 -&gt; mask=2047 (0x7FF)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">next_head </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (head </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mask_;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 1 周期 AND vs ~20-40 周期取模</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这就是 <code>--render_queue_capacity</code> 会向上取整的原因：任何值都会变成 2 的幂，从而启用 <code>&amp; mask_</code> 优化。容量 2048 实际存储 2047 个元素（保留一个槽位用于满/空区分）。</p></div><p>相同模式应用于其他地方：</p><ul><li>帧率日志：<code>(frames_rendered &amp; 63U) == 0U</code> 替代 <code>% 60</code></li><li>奇偶判断：<code>(x &amp; 1U) == 0U</code> 替代 <code>x % 2 == 0</code></li><li>整数减半：<code>x &gt;&gt; 1</code> 替代 <code>x / 2</code>（仅限整数）</li></ul><h2 id="线程安全" tabindex="-1">线程安全 <a class="header-anchor" href="#线程安全" aria-label="Permalink to &quot;线程安全&quot;">​</a></h2><ul><li>Widget 树仅在主线程访问</li><li>渲染队列是唯一的共享数据结构</li><li>渲染线程仅从队列读取 <code>RenderCommand</code>，不触碰 Widget 树</li><li>协程由 <code>EventLoop</code> 在主线程独占调度和恢复</li></ul><h2 id="数据走向深度解析" tabindex="-1">数据走向深度解析 <a class="header-anchor" href="#数据走向深度解析" aria-label="Permalink to &quot;数据走向深度解析&quot;">​</a></h2><p>本节追踪从用户输入到屏幕像素的完整帧流程。</p><h3 id="_1-输入接收-平台桥接" tabindex="-1">1. 输入接收（平台桥接） <a class="header-anchor" href="#_1-输入接收-平台桥接" aria-label="Permalink to &quot;1. 输入接收（平台桥接）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLFW 鼠标回调 / Android 触摸事件</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>PlatformBridge::input_callback_（由 Application 注册）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Application::DispatchPointerEvent(pos, action, button)</span></span></code></pre></div><p>平台桥接接收原始输入事件，通过注册的回调转发给 Application。桌面端 <code>GlfwBridge</code> 将 GLFW 枚举值转换为 <code>PlatformBridge::InputAction</code>（注意：GLFW_RELEASE=0 而 <code>kRelease=1</code>，需转换函数）。</p><h3 id="_2-命中测试与事件分发-application-层" tabindex="-1">2. 命中测试与事件分发（Application 层） <a class="header-anchor" href="#_2-命中测试与事件分发-application-层" aria-label="Permalink to &quot;2. 命中测试与事件分发（Application 层）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DispatchPointerEvent</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► HitTest(pos) ── 递归树遍历 ──► 最深层 Widget</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► OnPointerDown/Up/Move/Enter/Exit(local_pos)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └─► MarkFrameDirty()  ◄── 设置 frame_dirty_ = true</span></span></code></pre></div><p><code>HitTest</code> 按逆序遍历子节点（最上层优先），检查每个 Widget 的 <code>bounds_</code>。命中测试缓存避免布局未变时指针移动的重复遍历。拖拽进行中，移动事件绕过命中测试直接发给 pressed Widget。</p><h3 id="_3-widget-状态变更与脏标记" tabindex="-1">3. Widget 状态变更与脏标记 <a class="header-anchor" href="#_3-widget-状态变更与脏标记" aria-label="Permalink to &quot;3. Widget 状态变更与脏标记&quot;">​</a></h3><p>Widget 处理事件时（如 <code>Button</code> 改变按下状态、<code>Draggable</code> 更新偏移），调用 <code>MarkNeedsBuild()</code> 调度重建。这设置 Widget 的脏标志并向上传播标记帧脏。</p><h3 id="_4-帧构建-eventloop" tabindex="-1">4. 帧构建（EventLoop） <a class="header-anchor" href="#_4-帧构建-eventloop" aria-label="Permalink to &quot;4. 帧构建（EventLoop）&quot;">​</a></h3><p><code>frame_dirty_</code> 为 true 时，下一次 <code>EventLoop::Tick()</code> 执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tick()</span></span>
<span class="line"><span>  ├─► PollEvents()          ── 平台桥接轮询输入</span></span>
<span class="line"><span>  ├─► RunReadyCoroutines()  ── 4 阶段协程调度</span></span>
<span class="line"><span>  │     ├─ 提升 yield（yield_handles_ → pending）</span></span>
<span class="line"><span>  │     ├─ 恢复 pending 协程</span></span>
<span class="line"><span>  │     ├─ 清理完成（从 active_tasks_ 擦除）</span></span>
<span class="line"><span>  │     └─ 触发到期定时器（resume 前从 active_tasks_ 查 Task）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─► 构建脏 Widget         ── 有 needs_build_ 标志的 Widget 调用 Build()</span></span>
<span class="line"><span>  ├─► PerformLayout()       ── Taitank flexbox 布局遍历</span></span>
<span class="line"><span>  └─► Paint()               ── 生成 RenderCommand</span></span></code></pre></div><h3 id="_5-布局-taitank" tabindex="-1">5. 布局（Taitank） <a class="header-anchor" href="#_5-布局-taitank" aria-label="Permalink to &quot;5. 布局（Taitank）&quot;">​</a></h3><p><code>PerformLayout(width, height)</code> 遍历 Widget 树：</p><ol><li>每个 <code>Container</code> 创建/更新 Taitank flex 节点，设置属性（flex direction、padding、margin、justify/align）</li><li>叶子 Widget（<code>Text</code>、<code>Button</code>）通过 <code>OnMeasure()</code> 报告固有尺寸</li><li><code>Taitank::DoLayout(root_node, width, height)</code> 计算所有位置/大小</li><li><code>ReadLayoutRecursive()</code> 将计算出的边界复制回每个 Widget 的 <code>bounds_</code></li></ol><h3 id="_6-绘制与命令生成" tabindex="-1">6. 绘制与命令生成 <a class="header-anchor" href="#_6-绘制与命令生成" aria-label="Permalink to &quot;6. 绘制与命令生成&quot;">​</a></h3><p>每个 Widget 的 <code>Paint(RenderContext&amp;)</code> 方法发出 <code>RenderCommand</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Widget::Paint()</span></span>
<span class="line"><span>  ├─► MakeSave()              ── 压入变换/裁剪状态</span></span>
<span class="line"><span>  ├─► MakeTranslate(x, y)     ── 移动到 Widget 位置</span></span>
<span class="line"><span>  ├─► MakeClipRect(bounds)    ── 裁剪到 Widget 边界</span></span>
<span class="line"><span>  ├─► MakeDrawRect/RoundedRect ── 背景</span></span>
<span class="line"><span>  ├─► MakeDrawText(text, ...) ── 文本渲染</span></span>
<span class="line"><span>  ├─► children-&gt;Paint()       ── 递归</span></span>
<span class="line"><span>  └─► MakeRestore()           ── 弹出状态</span></span></code></pre></div><p>命令生成时即推入环形队列。一帧由 <code>MakeBeginFrame()</code> 和 <code>MakeEndFrame()</code> 命令界定。</p><h3 id="_7-spsc-环形队列传输" tabindex="-1">7. SPSC 环形队列传输 <a class="header-anchor" href="#_7-spsc-环形队列传输" aria-label="Permalink to &quot;7. SPSC 环形队列传输&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application (生产者)             Render (消费者)</span></span>
<span class="line"><span>       │                                  │</span></span>
<span class="line"><span>       │  TryPush(RenderCommand)          │</span></span>
<span class="line"><span>       │─────────────────────────────────►│</span></span>
<span class="line"><span>       │  (原子 head/tail，无锁)          │</span></span>
<span class="line"><span>       │                                  │  TryPop()</span></span>
<span class="line"><span>       │                                  │</span></span></code></pre></div><p>队列使用缓存行对齐的原子 head/tail 计数器避免伪共享。<code>std::construct_at</code> 在原始存储中构造元素；<code>std::destroy_at</code> 在 pop 后清理。容量向上取整为 2 的幂，通过位运算 AND 实现快速取模。</p><h3 id="_8-渲染线程消费" tabindex="-1">8. 渲染线程消费 <a class="header-anchor" href="#_8-渲染线程消费" aria-label="Permalink to &quot;8. 渲染线程消费&quot;">​</a></h3><p>渲染线程运行 <code>RenderLoop()</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RenderLoop()</span></span>
<span class="line"><span>  ├─► 等待帧信号（信号量，无任务时阻塞）</span></span>
<span class="line"><span>  ├─► MakeContextCurrent()   ── platform_bridge_-&gt;MakeContextCurrent()</span></span>
<span class="line"><span>  ├─► 消费队列中所有命令：</span></span>
<span class="line"><span>  │     ├─► BeginFrame       ── 清屏</span></span>
<span class="line"><span>  │     ├─► Save/Restore     ── 变换/裁剪栈</span></span>
<span class="line"><span>  │     ├─► DrawRect         ── 填充矩形</span></span>
<span class="line"><span>  │     ├─► DrawRoundedRect  ── 圆角矩形（着色器）</span></span>
<span class="line"><span>  │     ├─► DrawText         ── FontManager + tgfx 字形渲染</span></span>
<span class="line"><span>  │     └─► EndFrame</span></span>
<span class="line"><span>  └─► SwapBuffers()          ── platform_bridge_-&gt;SwapBuffers()</span></span></code></pre></div><p>桌面端 <code>GlfwBridge</code> 提供 OpenGL 上下文和窗口。移动端 <code>MobileBridge</code> 提供平台 Surface（ANativeWindow/CAMetalLayer），tgfx 直接渲染。</p><h3 id="_9-呈现" tabindex="-1">9. 呈现 <a class="header-anchor" href="#_9-呈现" aria-label="Permalink to &quot;9. 呈现&quot;">​</a></h3><p><code>SwapBuffers()</code> 将渲染好的帧呈现给窗口管理器。渲染线程随后在信号量上等待下一帧，空闲时 CPU 占用为零。</p><h2 id="rendercommand-类型" tabindex="-1">RenderCommand 类型 <a class="header-anchor" href="#rendercommand-类型" aria-label="Permalink to &quot;RenderCommand 类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>kNoop</code></td><td>无操作（填充）</td></tr><tr><td><code>kBeginFrame</code></td><td>开始新帧（清屏）</td></tr><tr><td><code>kEndFrame</code></td><td>结束帧（刷新）</td></tr><tr><td><code>kDrawRect</code></td><td>填充轴对齐矩形</td></tr><tr><td><code>kDrawRoundedRect</code></td><td>填充圆角矩形</td></tr><tr><td><code>kDrawText</code></td><td>指定位置、字体、字号、颜色的文本</td></tr><tr><td><code>kSave</code></td><td>压入变换/裁剪状态</td></tr><tr><td><code>kRestore</code></td><td>弹出变换/裁剪状态</td></tr><tr><td><code>kTranslate</code></td><td>应用平移偏移</td></tr><tr><td><code>kClipRect</code></td><td>设置裁剪矩形</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./widgets">Widget 系统</a></li><li><a href="./rendering">渲染管线</a></li><li><a href="./cross-platform">跨平台</a></li></ul>`,65)])])}const u=s(t,[["render",p]]);export{g as __pageData,u as default};
